// One item per Convex deployment, each with its own signed GET. Dev is always on
// ($env.CONVEX_SITE_URL); production is added when $env.CONVEX_SITE_URL_PROD is set. Each URL comes
// from the n8n environment, never the workflow. A GET signs the empty body: "sha256=" +
// hex(HMAC-SHA256(secret, timestamp + ".")). The secret stays in this node: items carry only the
// deployment name, its site URL and the signature.
const crypto = require('crypto');

const deployments = [];
if (!$env.CONVEX_SITE_URL) throw new Error('CONVEX_SITE_URL is not set in the n8n environment');
deployments.push({ deployment: 'dev', siteUrl: $env.CONVEX_SITE_URL });
if ($env.CONVEX_SITE_URL_PROD) deployments.push({ deployment: 'prod', siteUrl: $env.CONVEX_SITE_URL_PROD });

// Production may have its own secret; until it does, both deployments share one.
const secretFor = (deployment) =>
  deployment === 'prod' ? $env.N8N_TO_CONVEX_SECRET_PROD || $env.N8N_TO_CONVEX_SECRET : $env.N8N_TO_CONVEX_SECRET;

return deployments.map(({ deployment, siteUrl }) => {
  const secret = secretFor(deployment);
  if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set in the n8n environment');
  // Taken now, right before the request; the HTTP node's retries (3 tries, 10 s apart) finish
  // well inside Convex's 5-minute window.
  const timestamp = String(Date.now());
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.', 'utf8').digest('hex');
  return { json: { deployment, siteUrl: String(siteUrl).replace(/\/+$/, ''), timestamp, signature } };
});

// The HTTP node returns only the response, so each loan gets its deployment and site URL back
// from the signed GET it came from (paired item). The write-back then goes to that same
// deployment, so each deployment keeps its own <loanId>:<day> idempotency. A deployment whose GET
// failed is skipped here (its reminders don't block the other one's) and alerted on by
// "Alert on failures".
const signed = $('Sign GET overdue-loans').all();
const sourceOf = (item, index) => {
  const p = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  const at = p && typeof p.item === 'number' ? p.item : index;
  return (signed[at] || signed[index]).json;
};

const out = [];
$input.all().forEach((item, index) => {
  if (item.json.error) return;
  const { deployment, siteUrl } = sourceOf(item, index);
  const loans = Array.isArray(item.json.body) ? item.json.body : [];
  for (const loan of loans) out.push({ json: { ...loan, deployment, siteUrl } });
});
return out;

// Mock "Send reminder": stands in for an SMTP node. One JSON line per overdue loan goes to the
// outbox file. A failed send is not thrown: it becomes status "failed" with a short error, so
// Convex records the attempt instead of the whole run aborting.
const fs = require('fs');

// Keep only the first character and the domain: enough to tell recipients apart in a log.
const maskEmail = (email) => {
  const parts = String(email || '').split('@');
  if (parts.length !== 2 || !parts[0] || !parts[1]) return '***';
  return parts[0].slice(0, 1) + '***@' + parts[1];
};
const oneLine = (value, max) => String(value == null ? '' : value).replace(/\s+/g, ' ').trim().slice(0, max);

const outbox = $env.LENDLOOP_MOCK_OUTBOX;

const results = [];
for (const item of $input.all()) {
  const loan = item.json;
  if (!loan.loanId || !loan.idempotencyKey) {
    // Contract violation from Convex: nothing can be written back without these keys.
    throw new Error('overdue-loans item is missing loanId or idempotencyKey');
  }
  const base = { loanId: loan.loanId, idempotencyKey: loan.idempotencyKey, deployment: loan.deployment, siteUrl: loan.siteUrl };
  try {
    if (!outbox) throw new Error('LENDLOOP_MOCK_OUTBOX is not set');
    const entry = {
      at: new Date().toISOString(),
      channel: 'overdue-reminder',
      deployment: loan.deployment,
      loanId: loan.loanId,
      to: maskEmail(loan.borrowerEmail),
      subject: oneLine('Reminder: please return ' + loan.toolName, 200),
      message: oneLine(
        'Hi ' + loan.borrowerName + ', ' + loan.toolName + ' was due back on ' + loan.endDate +
          '. Please return it to its owner and ask them to mark it returned in LendLoop.',
        500,
      ),
    };
    fs.appendFileSync(outbox, JSON.stringify(entry) + '\n');
    results.push({ json: { ...base, status: 'sent', to: entry.to } });
  } catch (error) {
    results.push({ json: { ...base, status: 'failed', error: oneLine(error && error.message, 200) } });
  }
}
return results;

// Builds the exact JSON string that will be sent and signs that string. The HTTP node sends
// $json.body as a raw body, so the bytes Convex verifies are the bytes signed here. Each result
// goes back to the deployment its loan came from, signed with that deployment's secret.
// Signed per item, right before its POST, so a long list never ages a timestamp past 5 minutes.
const crypto = require('crypto');

const secretFor = (deployment) =>
  deployment === 'prod' ? $env.N8N_TO_CONVEX_SECRET_PROD || $env.N8N_TO_CONVEX_SECRET : $env.N8N_TO_CONVEX_SECRET;

return $input.all().map((item) => {
  const r = item.json;
  const secret = secretFor(r.deployment);
  if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set in the n8n environment');
  if (!r.siteUrl) throw new Error('reminder result has no siteUrl');
  const payload = { idempotencyKey: r.idempotencyKey, loanId: r.loanId, status: r.status };
  if (r.status === 'failed' && r.error) payload.error = String(r.error).slice(0, 200);
  const body = JSON.stringify(payload);
  const timestamp = String(Date.now());
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body, 'utf8').digest('hex');
  return { json: { deployment: r.deployment, siteUrl: r.siteUrl, body, timestamp, signature } };
});

// Runs last (it sits below the reminders branch, and n8n finishes one branch before the next). A
// deployment whose GET still failed after 3 tries is written to the outbox; write-backs that failed
// were already written by "Check write-backs". Then one error is thrown for all of them, so the
// error workflow alerts once, after every reachable loan got its reminder and write-back.
const fs = require('fs');
const signed = $('Sign GET overdue-loans').all();
const oneLine = (value, max) => String(value == null ? '' : value).replace(/\s+/g, ' ').trim().slice(0, max);
// Earlier nodes that may not have run (no overdue loans: the loop never started).
const ran = (name) => {
  try {
    const node = $(name);
    if (node.isExecuted === false) return [];
    return (node.all() || []).map((item) => item.json);
  } catch (error) {
    return [];
  }
};

const failed = [];
$input.all().forEach((item, index) => {
  if (!item.json.error) return;
  const p = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  const at = p && typeof p.item === 'number' ? p.item : index;
  const source = (signed[at] || signed[index]).json;
  const err = item.json.error;
  failed.push({ deployment: source.deployment, error: oneLine(typeof err === 'string' ? err : err && err.message, 200) });
});
const writeBacks = ran('Check write-backs');
if (failed.length === 0 && writeBacks.length === 0) return [];

if ($env.LENDLOOP_MOCK_OUTBOX) {
  for (const f of failed) {
    const entry = { at: new Date().toISOString(), channel: 'overdue-fetch-failed', deployment: f.deployment, error: f.error };
    fs.appendFileSync($env.LENDLOOP_MOCK_OUTBOX, JSON.stringify(entry) + '\n');
  }
}
const problems = [];
if (failed.length) problems.push('GET /n8n/overdue-loans failed for ' + failed.map((f) => f.deployment + ' (' + f.error + ')').join(', '));
if (writeBacks.length) {
  problems.push('reminder-status write-back failed for ' + writeBacks.map((w) => w.loanId + ' on ' + w.deployment + ' (' + w.error + ')').join(', '));
}
throw new Error(problems.join('; '));

// Runs once per loan, right after its write-back (the loop hands over one loan at a time). The
// HTTP node returns only Convex's answer, so the loan and deployment come from this turn's signed
// request. A write-back that failed after its 3 tries is kept as a result, not thrown: the other
// loans still get their reminder, and "Alert on failures" reports it at the end of the run.
const oneLine = (value, max) => String(value == null ? '' : value).replace(/\s+/g, ' ').trim().slice(0, max);

const signed = $('Sign POST reminder-status').first().json;
const request = JSON.parse(signed.body);
const answer = $input.first().json;
const err = answer.error;
const result = {
  deployment: signed.deployment,
  loanId: request.loanId,
  idempotencyKey: request.idempotencyKey,
  reminder: request.status,
  writeBack: err ? 'failed' : 'ok',
};
if (err) result.error = oneLine(typeof err === 'string' ? err : err.message || JSON.stringify(err), 200);
return [{ json: result }];

// The loop's "done" output: one result per loan. Failed write-backs are written to the outbox and
// passed on; "Alert on failures" raises one alert for them and any failed fetch.
const fs = require('fs');
const failed = $input.all().map((item) => item.json).filter((r) => r.writeBack === 'failed');
if ($env.LENDLOOP_MOCK_OUTBOX) {
  for (const f of failed) {
    const entry = { at: new Date().toISOString(), channel: 'overdue-writeback-failed', deployment: f.deployment, loanId: f.loanId, reminder: f.reminder, error: f.error };
    fs.appendFileSync($env.LENDLOOP_MOCK_OUTBOX, JSON.stringify(entry) + '\n');
  }
}
return failed.map((f) => ({ json: f }));
